def table(headers, rows):
    escape=lambda x:str(x).replace('|',' / ').replace('\n',' ')
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |']+['| '+' | '.join(escape(x) for x in row)+' |' for row in rows])+'\n'


def save(name,text):
    (DOCS/name).write_text(text)


